sys_data_source.data_loader:
(function loadData(import_set_table, data_source, import_log, last_success_import_time) {

    try {


        inputs = {};
        inputs['attachment_name'] = "test";

        var flowAction = sn_fd.FlowAPI.getRunner()
            .action('x_cesy_service_gr.copy_of_get_ceburu_devices')
            .inForeground()
            .withInputs(inputs)
            .run();


        // 3. Extract the outputs from the completed execution
        var outputs = flowAction.getOutputs();
        var attachmentSysId = outputs['response_body'];

        if (attachmentSysId && attachmentSysId.length == 32) {
            // gs.info('Ceburu Flow Success. Attachment found with ID: ' + attachmentSysId);

            // 4. Initialize the attachment API to extract the raw text content stream
            var attachmentAPI = new GlideSysAttachment();
            var contentStream = attachmentAPI.getContentStream(attachmentSysId);

            // Read the binary data stream lines into a standard string variable
            var reader = new GlideTextReader(contentStream);
            var rawJsonText = "";
            var line = "";

            while ((line = reader.readLine()) != null) {
                rawJsonText += line;
            }

            if (!rawJsonText) {
                gs.error('Ceburu Staging Error: Extracted attachment text file content is empty.');
            }

            // 5. Parse the raw text data into an actionable JSON object
            var responseBody = JSON.parse(rawJsonText);
        }
        var results = responseBody.results;


        for (var i = 0; i < results.length; i++) {

            var item = results[i];

            var spec = item.specifications && item.specifications.length > 0 ? item.specifications[0] : {};

            // =========================
            // DEVICE IMPORT RECORD
            // =========================

            var importRecord = {};

            importRecord.target_class = "";

            switch ((item.device.deviceType || "").toLowerCase()) {

                case "router":
                    importRecord.target_class = "cmdb_ci_ip_router";
                    break;

                case "switch":
                    importRecord.target_class = "cmdb_ci_switch";
                    break;

                case "firewall":
                    importRecord.target_class = "cmdb_ci_ip_firewall";
                    break;

                default:
                    importRecord.target_class = "";
            }

            // Identification
            importRecord.device_id = item.device.id;
            importRecord.correlation_id = item.device.id + "";

            // Name
            importRecord.name = spec.hostname || item.device.deviceName || "";
            importRecord.hostname = spec.hostname || "";

            // Classification
			importRecord.networkid = item.device.networkid;
            importRecord.device_type = item.device.deviceType || "";
            importRecord.device_role = item.device.deviceRole || "";

            // Networking
            importRecord.ip_address = item.device.deviceIP || spec.ipaddress || "";
            importRecord.mac_address = item.device.macaddress || "";

            // Vendor / Model
            importRecord.manufacturer = item.device.manufacture || "";
            importRecord.vendor = spec.vendor || "";
            importRecord.model = item.device.deviceModel || spec.model || "";
            importRecord.model_number = spec.model || "";

            // Hardware
            importRecord.serial_number = item.device.serialnumber || spec.serialno || "";

            // Operating System
            importRecord.os_name = spec.osname || "";
            importRecord.os_version = spec.softwareversion || "";
            importRecord.firmware_version = spec.currentversion || "";

            // Location
            importRecord.location = item.device.location || "";
            importRecord.country = item.device.countryname || "";

            // Discovery
            importRecord.discovery_source = "SG-Ceburu";
            importRecord.neighbours =
                (item.device.neighbour && item.device.neighbour.length) ?
                item.device.neighbour.join(",") :
                "";

            import_set_table.insert(importRecord);

            // =========================
            // INTERFACE IMPORT RECORD
            // =========================

            var interfaces = item.interfaces || [];
            for (var j = 0; j < interfaces.length; j++) {

                var iface = interfaces[j];

                importRecord = {};

                importRecord.type = "interface";

                // =========================
                // RELATIONSHIP TO PARENT DEVICE
                // =========================

                importRecord.device_id = item.device.id;

                // Identification
                importRecord.interface_id = iface.id || "";
                importRecord.correlation_id =
                    item.device.id + "_" + (iface.number || iface.name);

                // Basic info
                importRecord.name = iface.name || "";
                importRecord.interface_number = iface.number || "";
                importRecord.interface_type = iface.type || "";

                // Status
                importRecord.admin_status = iface.Adminstatus === true ? 1 : 2;
                importRecord.oper_status = iface.Operstatus === true ? 1 : 2;

                // Characteristics
                importRecord.speed = iface.speed || 0;
                importRecord.duplex = iface.duplex || "";
                importRecord.vlan = iface.vlan || "";

                // Topology
                importRecord.connected_device =
                    (iface.connecteddevice && iface.connecteddevice.length) ?
                    iface.connecteddevice.join(",") :
                    "";

                import_set_table.insert(importRecord);

            }
        }

    } catch (ex) {

        import_log.error('Load Data Error: ' + ex);

    }

})(import_set_table, data_source, import_log, last_success_import_time);

